// Header-only volume check: how many untranslated keys per project, account-wide.
// limit=1 and no include_translations, so this is one tiny request per project.
// Needed before committing the nightly to pulling translations for these keys -
// that is what made leading/trailing whitespace exceed the 900s timeout.
const out = [];
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase(),
      qa_type: '',
      qa_label: 'untranslated',
      extra: '&filter_untranslated=1'
    }});
  }
}
return out;

const reqs = $('Build QA Requests').all();
const res = $input.all();
const rows = [];
let grand = 0;
let failedCount = 0;
for (let i = 0; i < res.length; i++) {
  const metaItem = reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  const r = res[i].json || {};
  const hdr = r.headers || {};
  const raw = hdr['x-pagination-total-count'];
  let n = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const p = parseInt(raw, 10);
    if (!isNaN(p)) { n = p; }
  }
  if (n === null) { failedCount++; }
  else { grand += n; }
  if (n === null || n > 0) { rows.push({ project: meta.project_name, untranslated: n }); }
}
rows.sort(function (a, b) { return (b.untranslated || 0) - (a.untranslated || 0); });
return [{ json: {
  grand_total_untranslated_keys: grand,
  projects_with_untranslated: rows.length,
  projects_scanned: res.length,
  failed: failedCount,
  note: 'Counts include pseudo and archived - they are the raw header figure, an upper bound on what the nightly would need to fetch with translations.',
  rows: rows
}}];
